package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	if !scanner.Scan() {
		return
	}
	// N is read but not used in logic
	scanner.Text()

	if !scanner.Scan() {
		return
	}
	s := scanner.Text()

	parts := strings.Split(s, "W")
	var lengths []int
	for _, part := range parts {
		if part != "" {
			lengths = append(lengths, len(part))
		}
	}

	fmt.Println(len(lengths))
	for i, l := range lengths {
		if i > 0 {
			fmt.Print(" ")
		}
		fmt.Print(l)
	}
	fmt.Println()
}

